<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Our Rooms</title><link rel="stylesheet" href="<?=base_url('assets/css/website.css')?>"><style>.room-list{max-width:1180px;margin:45px auto;padding:20px;display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:22px}.room-card{border:1px solid #ddd;border-radius:12px;overflow:hidden;background:#fff}.room-card img{width:100%;height:220px;object-fit:cover}.room-card .body{padding:18px}.room-card a{display:inline-block;margin-top:12px;padding:10px 16px;background:#182b28;color:#fff;text-decoration:none;border-radius:5px}</style></head><body><?php $this->load->view('website/partials/navigation'); ?><main><div class="section-heading" style="text-align:center;padding:50px 20px 0"><p class="eyebrow">STAY WITH US</p><h1>Our Rooms</h1></div><div class="room-list"><?php foreach($rooms as $room): $img=!empty($room->images)?$room->images[0]->rmiPath:'';?><article class="room-card"><?php if($img):?><img src="<?=base_url($img)?>" alt="<?=html_escape($room->rmTitle)?>"><?php else:?><div style="height:220px;background:#eee"></div><?php endif;?><div class="body"><h2><?=html_escape($room->rmTitle)?></h2><p><?=html_escape($room->rmDesc)?></p><p>Capacity: <?=html_escape($room->rmCapacity)?> · ₱<?=number_format((float)$room->rmPrice,2)?> / night</p><a href="<?=base_url('rooms/'.$room->rmID)?>">View Room</a></div></article><?php endforeach;?><?php if(!$rooms):?><p>No rooms are currently available.</p><?php endif;?></div></main><?php $this->load->view('website/partials/footer'); ?></body></html>